<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api,ApiError,errorText} from '../api'
import {useAuth} from '../stores/auth'
import {date,listItems} from '../domain'
import type {Row} from '../domain'
const auth=useAuth(),route=useRoute(),router=useRouter(),items=ref<Row[]>([]),detail=ref<Row|null>(null),departments=ref<Row[]>([]),error=ref(''),busy=ref(false),loading=ref(false),dirty=ref(false),rows=ref<Row[]>([]),totp=ref(''),verifyNeeded=ref(false)
const fields=[{id:'content',name:'工作内容'},{id:'progress',name:'推进情况'},{id:'problem',name:'存在问题'},{id:'suggestion',name:'解决建议'},{id:'coordination',name:'需要领导协调解决工作'},{id:'timeRequirement',name:'时间要求'},{id:'remark',name:'备注'}]
const form=ref<Row>({title:'各部门重点工作及需领导协调解决问题收集',companyId:auth.me?.companyId,deadline:'',departmentIds:[]})
const creating=computed(()=>route.query.new==='1'),id=computed(()=>route.params.id),canCreate=computed(()=>(auth.me?.role==='ADMIN'&&auth.me.companyId==null||['GROUP_LEADER','DIVISION_LEADER','COMPANY_LEADER'].includes(auth.me?.role||''))&&(!auth.me?.permissions||auth.me.permissions.includes('TASK_CREATE')))
const companies=computed(()=>Array.from(new Map(departments.value.map(d=>[String(d.companyId),{id:d.companyId,name:d.companyName||'公司名称不可用'}])).values()))
const choices=computed(()=>departments.value.filter(d=>String(d.companyId)===String(form.value.companyId)))
const own=computed(()=>detail.value?.responses?.find((r:Row)=>String(r.deptId)===String(auth.me?.deptId)))
const editable=computed(()=>own.value?.canEdit&&(!auth.me?.permissions||auth.me.permissions.includes('TASK_UPDATE')))
const label=(value:string)=>({ACTIVE:'收集中',COMPLETED:'全部完成',DRAFT:'未提交',SUBMITTED:'已完成'} as Record<string,string>)[value]||value
const leaveCheck=()=>!dirty.value||window.confirm('当前表格修改尚未保存，是否离开？')
onBeforeRouteLeave(leaveCheck);onBeforeRouteUpdate(leaveCheck)
const blank=()=>Object.fromEntries(fields.map(f=>[f.id,'']))
watch(()=>form.value.companyId,()=>{form.value.departmentIds=[]})
let request=0
async function load(){if(dirty.value&&!window.confirm('当前修改尚未保存，是否重新加载？'))return;const run=++request;loading.value=true;error.value='';try{if(id.value){const d=await api.get<Row>('/collections/'+id.value);if(run!==request)return;detail.value=d;const response=d.responses.find((r:Row)=>String(r.deptId)===String(auth.me?.deptId));rows.value=response?.rows?.length?structuredClone(response.rows):[blank()]}else{const d=await api.get<Row[]>('/collections');if(run!==request)return;items.value=d;detail.value=null}dirty.value=false}catch(e){if(run===request)error.value=errorText(e)}finally{if(run===request)loading.value=false}}
async function create(){if(busy.value)return;if(!form.value.title.trim()||!form.value.companyId||!form.value.deadline||!form.value.departmentIds.length){error.value='请填写标题、公司、截止时间并选择接收部门';return}busy.value=true;error.value='';try{const d=await api.post('/collections',form.value);await router.push('/collections/'+d.id)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function save(submit=false){if(busy.value||!editable.value)return;busy.value=true;error.value='';try{const d=await api.post<Row>(`/collections/${id.value}/${submit?'submit':'draft'}`,{version:own.value.version,rows:rows.value});detail.value=d;const response=d.responses.find((r:Row)=>String(r.deptId)===String(auth.me?.deptId));rows.value=response?.rows?.length?structuredClone(response.rows):[blank()];dirty.value=false}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function download(){if(busy.value)return;busy.value=true;error.value='';try{if(verifyNeeded.value){await api.post('/auth/totp/verify',{code:totp.value});totp.value='';verifyNeeded.value=false}await api.download('/collections/'+id.value+'/export','部门填报汇总.xlsx')}catch(e){error.value=errorText(e);verifyNeeded.value=e instanceof ApiError&&e.code==='FRESH_TOTP_REQUIRED'}finally{busy.value=false}}
watch(()=>[route.params.id,route.query.new],()=>{dirty.value=false;void load()})
onMounted(()=>{void load();api.get('/organization/departments').then(d=>departments.value=listItems(d)).catch(e=>error.value=errorText(e))})
</script>
<template>
 <div class="backline"><router-link to="/tasks">← 任务中心</router-link><router-link v-if="id||creating" to="/collections">部门填表列表</router-link></div>
 <section class="page-heading"><div><p class="eyebrow">DEPARTMENT COLLECTION</p><h1>{{ creating?'发起部门填表':detail?.title||'部门填表' }}</h1><p class="muted">各部门自行填表，提交后即完成，无需审核。</p></div><router-link v-if="!id&&!creating&&canCreate" to="/collections?new=1"><el-button type="primary">＋ 发起填表</el-button></router-link><el-button v-if="!creating" :loading="loading" @click="load">刷新</el-button></section>
 <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
 <section v-if="creating&&canCreate" class="panel"><el-form label-position="top" @submit.prevent="create"><el-form-item label="填表标题" required><el-input v-model="form.title" maxlength="300"/></el-form-item><el-form-item label="所属公司" required><el-select v-model="form.companyId"><el-option v-for="c in companies" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item label="接收部门" required><el-select v-model="form.departmentIds" multiple filterable style="width:100%"><el-option v-for="d in choices" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="截止时间（北京时间）" required><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><p class="muted">表格包含：序号、工作内容、推进情况、存在问题、解决建议、需领导协调解决工作、时间要求、备注。每部门最多100行，所有单元格合计最多20000字。</p><el-button type="primary" native-type="submit" :loading="busy">发布填表</el-button></el-form></section>
 <div v-else-if="!id" class="collection-grid"><router-link v-for="item in items" :key="item.id" :to="'/collections/'+item.id" class="panel collection-card"><h2>{{ item.title }}</h2><p>{{ label(item.status) }} · {{ item.submitted }} / {{ item.departmentCount }} 个部门完成</p><small class="muted">截止 {{ date(item.deadline) }}</small></router-link><el-empty v-if="!loading&&!items.length" description="暂无需要填写或查看的表格"/></div>
 <template v-else-if="detail">
 <section class="panel collection-summary"><b>{{ label(detail.status) }}</b><span>截止 {{ date(detail.deadline) }}</span><span>{{ detail.submitted }} / {{ detail.departmentCount }} 个部门完成</span><el-button v-if="detail.canManage&&(!auth.me?.permissions||auth.me.permissions.includes('REPORTS'))" :loading="busy" @click="download">导出已提交汇总 Excel</el-button><template v-if="verifyNeeded"><el-input v-model="totp" maxlength="6" inputmode="numeric" placeholder="六位动态验证码" style="max-width:180px"/><el-button @click="download">验证并导出</el-button></template></section>
 <section v-if="own" class="panel response-panel"><div class="row-between"><h2>{{ own.departmentName }} · {{ label(own.status) }}</h2><span v-if="dirty" class="muted">有未保存修改</span></div><p v-if="!editable" class="muted">{{ own.status==='SUBMITTED'?'本部门已完成提交，内容已锁定。':'当前已截止或当前岗位仅可查看。' }}</p><div class="sheet-scroll" tabindex="0" aria-label="部门填报表格"><table><thead><tr><th>序号</th><th v-for="f in fields" :key="f.id">{{ f.name }}</th><th v-if="editable">操作</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><td>{{ index+1 }}</td><td v-for="f in fields" :key="f.id"><el-input v-if="editable" v-model="row[f.id]" type="textarea" :rows="3" maxlength="2000" :aria-label="'第'+(index+1)+'行'+f.name" @input="dirty=true"/><p v-else>{{ row[f.id]||'—' }}</p></td><td v-if="editable"><el-button text type="danger" @click="rows.splice(index,1);dirty=true">删除行</el-button></td></tr></tbody></table></div><div v-if="editable" class="collection-actions"><el-button :disabled="rows.length>=100||busy" @click="rows.push(blank());dirty=true">＋ 增加一行</el-button><el-button :loading="busy" @click="save(false)">保存草稿</el-button><el-popconfirm title="提交后即完成，不能再修改。确认提交？" @confirm="save(true)"><template #reference><el-button type="primary" :disabled="busy">提交表格</el-button></template></el-popconfirm></div></section>
 <section v-if="detail.canManage" class="panel response-panel"><h2>部门提交情况</h2><article v-for="response in detail.responses" :key="response.id" class="department-response"><h3>{{ response.departmentName }} · {{ label(response.status) }}</h3><small v-if="response.submittedAt" class="muted">提交于 {{ date(response.submittedAt) }}</small><p v-if="response.status!=='SUBMITTED'" class="muted">尚未提交，草稿由部门自行保存。</p><div v-else class="sheet-scroll" tabindex="0" :aria-label="response.departmentName+'已提交表格'"><table><thead><tr><th>序号</th><th v-for="f in fields" :key="f.id">{{ f.name }}</th></tr></thead><tbody><tr v-for="(row,index) in response.rows" :key="index"><td>{{ index+1 }}</td><td v-for="f in fields" :key="f.id"><p>{{ row[f.id]||'—' }}</p></td></tr></tbody></table></div></article></section>
 </template>
</template>
<style scoped>
.collection-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,320px),1fr));gap:18px}.collection-card h2{overflow-wrap:anywhere}.collection-summary{display:flex;gap:14px 22px;align-items:center;flex-wrap:wrap;font-size:12px}.response-panel{margin-top:20px}.sheet-scroll{overflow:auto;margin:16px 0;max-width:100%}table{border-collapse:collapse;width:100%;min-width:1250px;font-size:12px}th,td{border:1px solid var(--line);padding:10px;vertical-align:top;min-width:160px}th:first-child,td:first-child{min-width:48px;width:48px}th{background:var(--surface-muted);text-align:left}td p{white-space:pre-wrap;overflow-wrap:anywhere;margin:0;line-height:1.8}.collection-actions{display:flex;gap:10px;flex-wrap:wrap}.collection-actions .el-button+.el-button{margin-left:0}.department-response{border-top:1px solid var(--line);margin-top:16px;padding-top:16px}.page-heading{flex-wrap:wrap}.backline{flex-wrap:wrap}
</style>
